// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Validate environment variables
if (!SUPABASE_URL) {
  console.error('❌ VITE_SUPABASE_URL is not defined');
  throw new Error('VITE_SUPABASE_URL environment variable is required');
}

if (!SUPABASE_PUBLISHABLE_KEY) {
  console.error('❌ VITE_SUPABASE_PUBLISHABLE_KEY is not defined');
  throw new Error('VITE_SUPABASE_PUBLISHABLE_KEY environment variable is required');
}

console.log('✅ Supabase client initialized with URL:', SUPABASE_URL);

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    // تجاوز navigator.locks الذي قد يعلق إذا بقي قفل قديم من تبويب سابق
    // lockNoOp: ينفذ العملية مباشرة بدون قفل — آمن لتطبيق تبويب واحد
    lock: async (name: string, acquireTimeout: number, fn: () => Promise<any>) => {
      return await fn();
    },
  },
  // إعدادات Realtime محسّنة للعمل داخل Capacitor (WebSocket keepalive)
  realtime: {
    params: {
      eventsPerSecond: 10,
    },
    heartbeatIntervalMs: 15000,   // نبضة كل 15 ثانية للحفاظ على الاتصال
    reconnectAfterMs: (tries: number) => {
      // إعادة الاتصال سريعاً: 0.5s, 1s, 2s, 4s, max 10s
      return Math.min(500 * Math.pow(2, tries), 10000);
    },
  },
  // Add error handling and logging
  global: {
    headers: {
      'X-Client-Info': 'raan-captain-app',
    },
  },
});